import org.openenglish.reader.*;import java.util.*;import java.io.*;import java.nio.file.*;import java.util.concurrent.*;import android.content.*;import android.os.Build;
public final class IslandUsabilityTest {
 static int checks;static void check(boolean ok,String s){if(!ok)throw new AssertionError(s);checks++;System.out.println("PASS "+s);}static void reset(){LocalModels.calls.clear();LocalNative.calls.clear();LocalNative.duringWhisper=()->{};LocalModels.installed=true;LocalModels.selected=LocalModels.QWEN;}
 public static void main(String[] args)throws Exception {
  WorkBudget w=new WorkBudget(1000,90000,45000);check(!w.expired(45999)&&w.expired(46000),"generation with no visible output reaches idle deadline");w.progress(45000,3);check(!w.expired(89999),"increasing output extends idle wait");check(w.expired(91000),"total generation deadline remains bounded despite output");w=new WorkBudget(0,90000,45000);w.progress(44000,4);w.progress(88000,4);check(w.expired(89000),"duplicate output cannot hold request open");w=new WorkBudget(0,90000,45000);w.progress(44000,4);w.progress(88000,2);check(w.expired(89000),"shorter replacement output does not renew wait");w=new WorkBudget(500,45000,0);check(!w.expired(45499)&&w.expired(45500),"ASR has total deadline without idle requirement");w=new WorkBudget(0,120000,0);w.progress(110000,100);check(w.expired(120000),"model warmup cannot extend total deadline");check(w.seconds(3500)==3&&w.seconds(-1)==0,"elapsed display uses monotonic duration");
  w=new WorkBudget(0,100,0);w.complete();check(w.completed()&&!w.expired(1000),"durably completed operation cannot become a timeout");w.progress(2000,20);check(!w.expired(100000),"late progress cannot reopen completed deadline");VoiceTurns turns=new VoiceTurns();long turn=turns.next();WorkBudget committed=new WorkBudget(0,100,0);turns.commit(turn,committed::complete);synchronized(turns){if(!committed.completed()&&committed.expired(200))turns.next();}check(turns.current(turn)&&committed.completed(),"completion boundary wins over later timeout cancellation");
  PracticePath path=new PracticePath(Arrays.asList("a","a","b","c","d","../outside"),0);check(path.ids().equals(Arrays.asList("a","b","c")),"small adventure removes repeated IDs and caps at three");check(!path.rate("b")&&path.position()==0,"rating unrelated lesson cannot advance path");check(path.rate("a")&&path.current().equals("b"),"explicit rating advances exactly one lesson");check(!path.rate("a")&&path.position()==1,"duplicate callback cannot advance next lesson");PracticePath restored=new PracticePath(path.ids(),path.position());check(restored.current().equals("b"),"rotation restores exact next lesson");restored.rate("b");restored.rate("c");check(restored.finished()&&restored.current().isEmpty()&&!restored.rate("c"),"completion remains idempotent");check(new PracticePath(Arrays.asList("../bad",null,"valid"),-7).current().equals("valid"),"invalid restored IDs discarded and cursor bounded");check(new PracticePath(Collections.emptyList(),10).finished(),"empty review path has no phantom lesson");
  File dir=Files.createTempDirectory("warm-route-").toFile();Context c=new Context(dir,dir);List<String> stages=new ArrayList<>();reset();LocalAI.warmIsland(c,new CloudClient.Job(),false,stages::add);check(LocalModels.calls.isEmpty()&&LocalNative.calls.size()==2&&LocalNative.calls.get(0).equals("loadLlama"),"text warmup never extracts or loads Whisper/VAD");check(stages.get(0).contains("qwen")&&stages.get(stages.size()-1).contains("就绪"),"text warmup has ordered ready progress");check(LocalNative.decode==0,"warmup does not run a discarded inference");
  reset();stages.clear();LocalAI.warmIsland(c,new CloudClient.Job(),true,stages::add);check(LocalModels.calls.equals(Arrays.asList("vad","multi")),"voice preparation still warms bundled recognition");check(LocalNative.calls.get(0).equals("loadWhisper")&&LocalNative.calls.get(2).equals("loadLlama"),"voice warms recognition before teacher");check(stages.size()==4&&stages.get(0).contains("人声")&&stages.get(1).contains("Whisper"),"voice stage reports are explicit");
  reset();CloudClient.Job cancelled=new CloudClient.Job();cancelled.cancel();boolean failed=false;try{LocalAI.warmIsland(c,cancelled,false,s->{});}catch(CancellationException e){failed=true;}check(failed&&LocalNative.calls.isEmpty(),"cancelled preparation does not load a model");reset();CloudClient.Job during=new CloudClient.Job();LocalNative.duringWhisper=during::cancel;failed=false;try{LocalAI.warmIsland(c,during,true,s->{});}catch(CancellationException e){failed=true;}check(failed&&!LocalNative.calls.contains("loadLlama"),"cancellation between speech and teacher prevents extra warmup");
  reset();LocalModels.installed=false;failed=false;try{LocalAI.warmIsland(c,new CloudClient.Job(),false,s->{});}catch(IOException e){failed=true;}check(failed&&LocalNative.calls.isEmpty(),"missing teacher does not waste voice model loading for text");reset();LocalModels.selected=LocalModels.DEEPSEEK;LocalAI.warmIsland(c,new CloudClient.Job(),false,s->{});check(LocalNative.calls.get(1).endsWith("deepseek"),"chosen teacher preserved in text warmup");reset();Build.SUPPORTED_ABIS=new String[]{"x86"};failed=false;try{LocalAI.warmIsland(c,new CloudClient.Job(),false,s->{});}catch(IOException e){failed=true;}check(failed&&LocalNative.calls.isEmpty(),"unsupported ABI fails before engines are loaded");System.out.println("USABILITY_CHECKS: "+checks);
 }
}
